[{"table_name":"corrective_action_submission","name":"immutable_submission","enabled":"O","definition":"CREATE TRIGGER immutable_submission BEFORE DELETE OR UPDATE ON corrective_action_submission FOR EACH ROW EXECUTE FUNCTION mf08_immutable_history()","function_name":"mf08_immutable_history","configuration":null,"body":"
      BEGIN
        IF TG_TABLE_NAME = 'safety_workflow_audit' OR TG_OP = 'DELETE' OR OLD.status <> 'PENDING' THEN
          RAISE EXCEPTION 'MF08 history is immutable';
        END IF;
        IF NEW.id IS DISTINCT FROM OLD.id OR NEW.corrective_action_id IS DISTINCT FROM OLD.corrective_action_id
          OR NEW.submitted_by IS DISTINCT FROM OLD.submitted_by OR NEW.result_description IS DISTINCT FROM OLD.result_description
          OR NEW.evidence_id IS DISTINCT FROM OLD.evidence_id OR NEW.submitted_at IS DISTINCT FROM OLD.submitted_at
          OR NEW.status = 'PENDING' THEN RAISE EXCEPTION 'Only a pending submission decision may be written'; END IF;
        RETURN NEW;
      END "}]

[{"table_name":"safety_workflow_audit","name":"immutable_workflow_audit","enabled":"O","definition":"CREATE TRIGGER immutable_workflow_audit BEFORE DELETE OR UPDATE ON safety_workflow_audit FOR EACH ROW EXECUTE FUNCTION mf08_immutable_history()","function_name":"mf08_immutable_history","configuration":null,"body":"
      BEGIN
        IF TG_TABLE_NAME = 'safety_workflow_audit' OR TG_OP = 'DELETE' OR OLD.status <> 'PENDING' THEN
          RAISE EXCEPTION 'MF08 history is immutable';
        END IF;
        IF NEW.id IS DISTINCT FROM OLD.id OR NEW.corrective_action_id IS DISTINCT FROM OLD.corrective_action_id
          OR NEW.submitted_by IS DISTINCT FROM OLD.submitted_by OR NEW.result_description IS DISTINCT FROM OLD.result_description
          OR NEW.evidence_id IS DISTINCT FROM OLD.evidence_id OR NEW.submitted_at IS DISTINCT FROM OLD.submitted_at
          OR NEW.status = 'PENDING' THEN RAISE EXCEPTION 'Only a pending submission decision may be written'; END IF;
        RETURN NEW;
      END "}]

[{"table_name":"worker_schedule","name":"mf03_one_shift_per_day","enabled":"O","definition":"CREATE TRIGGER mf03_one_shift_per_day BEFORE INSERT OR UPDATE ON worker_schedule FOR EACH ROW EXECUTE FUNCTION mf03_one_shift_per_day()","function_name":"mf03_one_shift_per_day","configuration":null,"body":"
      BEGIN
        IF NEW.is_active THEN
          PERFORM pg_advisory_xact_lock(hashtext(NEW.site_id::text||NEW.worker_id::text||NEW.work_date::text));
          IF EXISTS(SELECT 1 FROM worker_schedule WHERE site_id=NEW.site_id AND worker_id=NEW.worker_id AND work_date=NEW.work_date AND is_active AND id<>NEW.id) THEN
            IF TG_OP='UPDATE' AND OLD.is_active AND OLD.site_id=NEW.site_id AND OLD.worker_id=NEW.worker_id AND OLD.work_date=NEW.work_date AND OLD.shift_id=NEW.shift_id THEN RETURN NEW; END IF;
            RAISE EXCEPTION 'Worker already has an active shift on this date' USING ERRCODE='23505',CONSTRAINT='uq_worker_schedule_one_day';
          END IF;
        END IF;
        RETURN NEW;
      END "}]

[{"table_name":"contractor_team_membership","name":"team_membership_scope","enabled":"O","definition":"CREATE TRIGGER team_membership_scope BEFORE INSERT OR UPDATE ON contractor_team_membership FOR EACH ROW EXECUTE FUNCTION validate_team_membership_scope()","function_name":"validate_team_membership_scope","configuration":null,"body":" BEGIN
        IF NEW.left_at IS NULL AND NOT EXISTS (
          SELECT 1 FROM worker w JOIN contractor_team t ON t.id=NEW.team_id AND t.site_id=w.site_id AND t.contractor_id=w.contractor_id
          WHERE w.id=NEW.worker_id AND w.site_id=NEW.site_id AND w.contractor_id=NEW.contractor_id AND w.is_active AND t.is_active
        ) THEN RAISE EXCEPTION 'Invalid active team membership scope' USING ERRCODE='23514'; END IF;
        RETURN NEW; END "}]
